#include <stdio.h>
#include <string.h>
#include "solution.c"
static void decode_empty(char *text) { if(strcmp(text,"_")==0) text[0]='\0'; }
int main(void) {
    unsigned steps; if(scanf("%u",&steps)!=1 || steps>1000) return 2;
    Dict *dict=dict_create(); if(!dict) return 3;
    for(unsigned i=0;i<steps;++i) {
        char op[16],key[256],value[256];
        if(scanf("%15s%255s",op,key)!=2) {dict_destroy(dict);return 2;}
        decode_empty(key);
        if(strcmp(op,"P")==0) {
            if(scanf("%255s",value)!=1) {dict_destroy(dict);return 2;}
            decode_empty(value);printf("%d\n",(int)dict_put(dict,key,value));
        } else if(strcmp(op,"G")==0) {
            const char *found=dict_get(dict,key);
            if(found) printf("V %s\n",found); else puts("N");
        } else if(strcmp(op,"D")==0) printf("%d\n",(int)dict_remove(dict,key));
        else {dict_destroy(dict);return 2;}
    }
    printf("S %zu\n",dict_size(dict));dict_destroy(dict);return 0;
}

